}

type Result struct {
	Errors []Error `json:"errors"`
}

type validationErrors struct{ errors []error }

func (e validationErrors) Error() string {
	messages := make([]string, 0, len(e.errors))
	for _, issue := range e.errors {
		messages = append(messages, issue.Error())
	}
	return ErrValidationFailed.Error() + ": " + strings.Join(messages, "; ")
}
func (e validationErrors) Unwrap() []error      { return e.errors }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

// Unwrap returns the individual errors from a multi-error validation result.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if errors.As(err, &multi) {
