type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks schema and references in one configuration file.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return err
	}
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return err
	}
	err = v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))
	var issues []error
	for _, e := range cueerrors.Errors(err) {
		issue := Error{Message: e.Error(), Location: Location{File: file, Line: 1, Column: 1}}
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
		}
		issues = append(issues, issue)
	}
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return err
	}
	if len(root.Content) > 0 {
		issues = append(issues, referenceErrors(file, root.Content[0])...)
	}
	if len(issues) > 0 {
		return validationErrors{issues}
	}
	return nil
}

func field(n *yamlv3.Node, name string) *yamlv3.Node {
	if n == nil || n.Kind != yamlv3.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == name {
			return n.Content[i+1]
		}
	}
	return nil
}

func entries(n *yamlv3.Node) []*yamlv3.Node {
	if n != nil && n.Kind == yamlv3.SequenceNode {
		return n.Content
	}
	return nil
}

func value(n *yamlv3.Node) string {
	if n != nil {
		return n.Value
	}
	return ""
}

func referenceErrors(file string, doc *yamlv3.Node) []error {
	var issues []error
	add := func(message string, n *yamlv3.Node) {
		issues = append(issues, Error{Message: message, Location: Location{File: file, Line: n.Line, Column: n.Column}})
	}
	ns := value(field(doc, "namespace"))
	if ns == "" {
		ns = "default"
	}
	segments := map[string]bool{}
	for _, s := range entries(field(doc, "segments")) {
		segments[value(field(s, "key"))] = true
	}
	for _, flag := range entries(field(doc, "flags")) {
		key := value(field(flag, "key"))
		variants := map[string]bool{}
		for _, variant := range entries(field(flag, "variants")) {
			variants[value(field(variant, "key"))] = true
		}
		for i, rule := range entries(field(flag, "rules")) {
			prefix := fmt.Sprintf("flag %s/%s rule %d references unknown", ns, key, i+1)
			segment := field(rule, "segment")
			if segment != nil {
				if segment.Kind == yamlv3.ScalarNode && !segments[segment.Value] {
					add(fmt.Sprintf("%s segment %q", prefix, segment.Value), segment)
				} else if segment.Kind == yamlv3.MappingNode {
					for _, s := range entries(field(segment, "keys")) {
						if !segments[s.Value] {
							add(fmt.Sprintf("%s segment %q", prefix, s.Value), s)
						}
					}
				}
			}
			for _, dist := range entries(field(rule, "distributions")) {
				variant := field(dist, "variant")
				if variant != nil && !variants[variant.Value] {
					add(fmt.Sprintf("%s variant %q", prefix, variant.Value), variant)
				}
			}
		}
	}
	return issues
}

